<?php
ini_set("display_errors", 1);
error_reporting(E_ALL);
header("Content-Type: application/json; charset=utf-8");
header("Access-Control-Allow-Origin: *");

$results = [];

// 1. HomeworkController.php dosyasini guncelle
$targetFile = __DIR__ . "/../app/Http/Controllers/HomeworkController.php";
$b64Content = "";
$content = base64_decode($b64Content);

if (file_put_contents($targetFile, $content)) {
    $results["HomeworkController.php"] = "BASARIYLA GUNCELLENDI (" . strlen($content) . " bayt)";
} else {
    $results["HomeworkController.php"] = "YAZMA HATASI - Dosya izinlerini kontrol edin";
}

// 2. Laravel onbelleklerini temizle
try {
    require __DIR__ . "/../vendor/autoload.php";
    $app = require_once __DIR__ . "/../bootstrap/app.php";
    $kernel = $app->make(\Illuminate\Contracts\Console\Kernel::class);
    $kernel->bootstrap();

    \Illuminate\Support\Facades\Artisan::call("optimize:clear");
    $results["cache_clear"] = "Onbellek temizlendi (optimize:clear)";

    // 3. Test: Ogretmen icin odev listesini ve istatistikleri test et
    $teacher = \AppModels\User::find(8);
    if ($teacher) {
        \Illuminate\Support\Facades\Auth::login($teacher);
        $controller = $app->make(\App\Http\Controllers\HomeworkController::class);

        // Bekleyenler testi
        request()->replace(["is_checked" => "0", "per_page" => 5]);
        $respPending = $controller->index();
        $pendingData = $respPending->getData(true)["data"] ?? [];

        // Arsiv testi
        request()->replace(["is_checked" => "1", "per_page" => 5]);
        $respArchived = $controller->index();
        $archivedData = $respArchived->getData(true)["data"] ?? [];

        $results["test_results"] = [
            "pending_count" => $pendingData["pagination"]["total"] ?? null,
            "archived_count" => $archivedData["pagination"]["total"] ?? null,
            "stats" => $pendingData["stats"] ?? null,
        ];
    }
} catch (\Throwable $e) {
    $results["error"] = $e->getMessage() . " at " . $e->getFile() . ":" . $e->getLine();
}

echo json_encode([
    "success" => true,
    "results" => $results
], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
